using System;using System.IO;
public static class PaletteTable82 {
 public static void Main(string[] args){using(var r=new BinaryReader(File.OpenRead(args[0])))using(var w=new BinaryWriter(new FileStream(args[1],FileMode.Create)))using(var detail=args.Length==3?new BinaryWriter(new FileStream(args[2],FileMode.Create)):null){int n=r.ReadInt32(),levels=r.ReadInt32();if(n<1||n>16384||levels<2||levels>256)throw new ArgumentException("bounded source table");var p=new SourcePalette58.Settings{count=levels,darkLRatio=r.ReadDouble(),darkCRatio=r.ReadDouble(),gamma=r.ReadDouble(),intervalScale=r.ReadDouble()};for(int i=0;i<n;i++){var rgb=new[]{r.ReadInt32(),r.ReadInt32(),r.ReadInt32()};var a=SourcePalette58.MakePalette(new SourcePalette58.Reference{rgb8=rgb},p);for(int k=0;k<levels;k++){foreach(int v in a.rgb8[k])w.Write((byte)v);if(detail!=null){var lab=SourcePalette58.LabRGB(rgb);var x=SourcePalette58.LinearLch(a.targetL[k],a.usedC[k],Math.Atan2(lab[2],lab[1]));detail.Write(.2126*x[0]+.7152*x[1]+.0722*x[2]);detail.Write(a.actualL[k]);}}}if(r.BaseStream.Position!=r.BaseStream.Length)throw new ArgumentException("trailing source table");}}
}
